import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    parsed = list(reader)

    def clean(value):
        return value.lstrip("\ufeff") if value else value

    header_index = None
    for index, row in enumerate(parsed):
        normalized = [clean(value).strip().lower() for value in row]
        if "directorate" in normalized and "paid date" in normalized:
            header_index = index
            break

    if header_index is None:
        candidates = [
            (sum(bool(clean(value).strip()) for value in row), index)
            for index, row in enumerate(parsed)
            if row and any(clean(value).strip() for value in row)
        ]
        if not candidates:
            return {"columns": [], "rows": []}
        header_index = max(candidates)[1]
        if candidates and max(candidates)[0] < 2:
            return {"columns": [], "rows": []}

    columns = [clean(value) for value in parsed[header_index]]
    rows = [
        [clean(value) for value in row]
        for row in parsed[header_index + 1:]
        if row
    ]

    width = max([len(columns)] + [len(row) for row in rows])
    while len(columns) < width:
        columns.append("Extra {}".format(len(columns) - len(parsed[header_index]) + 1))

    normalized_rows = []
    for row in rows:
        normalized_rows.append(row + [""] * (width - len(row)))

    return {"columns": columns, "rows": normalized_rows}
